      if (provider === 'baidu') return '\u8BF7\u4F7F\u7528\u767E\u5EA6\u7F51\u76D8 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'pan189') return '\u8BF7\u4F7F\u7528\u5929\u7FFC\u4E91\u76D8 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'bili') return '\u8BF7\u4F7F\u7528\u54D4\u54E9\u54D4\u54E9 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'guangya') return '\u8BF7\u4F7F\u7528\u5149\u9E2D App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
